// Normalises the POST body of the PRD Genie API into the pipeline's input shape.
// Body fields:
//   input_text   (string)  transcript / brief / notes (also accepts "transcript" or "text")
//   input_type   (string)  optional hint: meeting_transcript | product_brief | stakeholder_notes | meeting_notes
//   mode         (string)  full (default) | extract_only | from_extraction
//   extraction   (object)  required for mode=from_extraction (the PM-reviewed output of an extract_only run)
//   test_id      (string)  optional: T1..T10 to run the baseline eval checks on this input
//   product_name (string)  optional hint
const b = $json.body || {};
const mode = ['full', 'extract_only', 'from_extraction'].includes(b.mode) ? b.mode : 'full';
return {
  json: {
    source: 'webhook',
    test_id: b.test_id || null,
    input_type: b.input_type || 'auto',
    mode,
    product_name: b.product_name || null,
    input_text: (b.input_text || b.transcript || b.text || '').toString(),
    reviewed_extraction: b.extraction ?? null,
  },
};

// ===================== PRD GENIE CONFIG — edit these values =====================
const CONFIG = {
  llm_base_url: 'https://api.openai.com/v1',   // any OpenAI-compatible /chat/completions endpoint
  model: 'gpt-4.1-mini',                       // model used by all 5 agents
  temperature: 0,                              // set to null for models that reject temperature
  price_per_1m_input_usd: 0.40,                // used for per-run cost tracking
  price_per_1m_output_usd: 1.60,
  langfuse_enabled: true,                      // set false to skip observability
  langfuse_host: 'https://cloud.langfuse.com', // or https://us.cloud.langfuse.com / self-hosted URL
};
// ================================================================================

// Company PRD template (Resources/prd_template.md) — the PRD Generator must follow it exactly.
const PRD_TEMPLATE = `# Product Requirements Document (PRD) Template

## 1. Product Overview
- **Product Name:**
- **Document Version:**
- **Author:**
- **Date:**
- **Status:** [Draft / In Review / Approved]

## 2. Goals and Objectives
- **Business Goal:** What business outcome does this feature drive?
- **User Goal:** What problem does this solve for the user?
- **Success Metrics:** How will we measure success? (list 2-3 KPIs)

## 3. User Personas
For each persona, describe:
- **Name / Role:**
- **Key Need:**
- **Current Workaround:**

## 4. Feature Requirements

### 4.1 Functional Requirements
| ID | Requirement | Priority (Must/Should/Nice) | Source |
|----|-------------|---------------------------|--------|
| FR-001 | | | |
| FR-002 | | | |

### 4.2 Non-Functional Requirements
| ID | Requirement | Category | Target |
|----|-------------|----------|--------|
| NFR-001 | | Performance | |
| NFR-002 | | Security | |

## 5. Acceptance Criteria
For each key feature, list specific testable criteria:
- **Feature X:**
  - [ ] Criteria 1
  - [ ] Criteria 2

## 6. Out of Scope
List what is explicitly NOT included in this release.

## 7. Dependencies
| Dependency | Owner | Status | Risk |
|-----------|-------|--------|------|
| | | | |

## 8. Assumptions
List assumptions made during requirement gathering.

## 9. Open Questions
List unresolved items that need stakeholder input.

## 10. Timeline
| Milestone | Target Date |
|-----------|-------------|
| Design Complete | |
| Development Start | |
| QA / Testing | |
| Launch | |`;

const rid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const ctx = {
  source: $json.source || 'eval',
  test_id: $json.test_id || null,
  input_type: $json.input_type || 'auto',
  mode: $json.mode || 'full',
  product_name: $json.product_name || null,
  input_text: ($json.input_text || '').toString(),
  config: CONFIG,
  prd_template: PRD_TEMPLATE,
  run_id: `prdgenie-${$execution.id}-${$json.test_id || 'run'}-${rid()}`,
  started_at: new Date().toISOString(),
  human_reviewed: false,
  trace: [],
};

// route: 0 = extract from source, 1 = skip to PRD (PM-reviewed extraction), 2 = stop (nothing to process)
if (ctx.mode === 'from_extraction') {
  let ex = $json.reviewed_extraction;
  if (typeof ex === 'string') { try { ex = JSON.parse(ex); } catch (e) { ex = null; } }
  if (ex && typeof ex === 'object') {
    ctx.extraction = ex;
    ctx.human_reviewed = true;
    ctx.route = ex.input_assessment?.sufficiency === 'insufficient' ? 2 : 1;
  } else {
    ctx.error = 'mode "from_extraction" requires an "extraction" object (the reviewed output of an extract_only run).';
    ctx.route = 2;
  }
} else if (ctx.input_text.trim().length === 0) {
  // Deterministic guard: never call the LLM (or generate a PRD) from nothing.
  ctx.extraction = {
    input_assessment: { input_type: ctx.input_type, sufficiency: 'insufficient', sufficiency_reason: 'Input text is empty.', summary: '' },
    requirements: [],
    missing_information: [{ area: 'Everything', question: 'No transcript or notes were provided. Please supply the meeting transcript, brief or notes.' }],
  };
  ctx.route = 2;
} else {
  ctx.route = 0;
}
return { json: ctx };

function parseLLM(resp) {
  const raw = resp?.choices?.[0]?.message?.content ?? '';
  try { return JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) {} }
    return { _parse_error: true, _raw: raw };
  }
}
function traceEntry(stage, prev, resp, parsed) {
  return {
    stage,
    model: resp.model || prev.config.model,
    start_time: prev._stage_start,
    end_time: new Date().toISOString(),
    input: prev.llm_request.messages,
    output: parsed,
    usage: { input: resp.usage?.prompt_tokens || 0, output: resp.usage?.completion_tokens || 0 },
  };
}
function nextCtx(prevNodeName, stage) {
  const prev = $(prevNodeName).item.json;
  const parsed = parseLLM($json);
  const ctx = { ...prev };
  delete ctx.llm_request;
  delete ctx._stage_start;
  return { ctx, parsed, entry: traceEntry(stage, prev, $json, parsed) };
}

const { ctx, parsed, entry } = nextCtx('Prepare Extractor Prompt', 'requirement_extractor');
ctx.trace = [...ctx.trace, entry];
ctx.extraction = parsed;

// route: 0 = continue to PRD generation, 1 = stop and assemble (extract_only / insufficient / error)
if (parsed._parse_error) {
  ctx.error = 'Requirement Extractor returned invalid JSON.';
  ctx.route = 1;
  return { json: ctx };
}
const stated = (parsed.requirements || []).filter(r => r.certainty === 'stated');
if (parsed.input_assessment?.sufficiency === 'insufficient') {
  ctx.stop_reason = 'Extractor flagged the input as insufficient.';
  ctx.route = 1;
} else if (stated.length === 0) {
  // Deterministic guard: only ambiguous items -> do not let later agents invent a PRD.
  parsed.input_assessment = { ...(parsed.input_assessment || {}), sufficiency: 'insufficient',
    sufficiency_reason: (parsed.input_assessment?.sufficiency_reason || '') + ' [PRD Genie guard: no stated requirements, only ambiguous items.]' };
  ctx.stop_reason = 'No stated (concrete) requirements were found.';
  ctx.route = 1;
} else if (ctx.mode === 'extract_only') {
  ctx.route = 1;
} else {
  ctx.route = 0;
}
return { json: ctx };

// Agent 2 — PRD Generator: structures the extraction into the company PRD template.
const SYSTEM = `You are the PRD GENERATOR agent of "PRD Genie". You turn a structured requirement EXTRACTION into a PRD that follows the company TEMPLATE exactly.

RULES
1. Content must come ONLY from the EXTRACTION JSON (the SOURCE is given for verification). Never add features, requirements, metrics, personas, dates, owners or numbers that are not there. No general product knowledge.
2. Keep every section and heading of the TEMPLATE, in the same order and numbering (sections 1-10, including 4.1 and 4.2). If a section has no source content write "_Not specified in source - see Open Questions._" Never drop a section.
3. 4.1 Functional Requirements table: one row per functional requirement with certainty "stated" (IDs FR-001, FR-002 ...). Priority column: Must / Should / Nice mapped from priority_signal; "unspecified" -> "TBD". Source column: the REQ id plus speaker if known, e.g. "REQ-001 (Sarah)".
4. 4.2 Non-Functional Requirements table: every non_functional requirement and every quantitative constraint, Category from nfr_category, Target copied verbatim (no rounding, no unit conversion).
5. 5. Acceptance Criteria: use acceptance_criteria_verbatim exactly as written, as "- [ ]" items. Where a requirement has none, only restate what the requirement itself makes testable and suffix "(derived from REQ-xxx)". Never add new conditions.
6. Ambiguous items are NOT firm requirements: list them in 9. Open Questions as "AMBIGUOUS: ..." with what must be clarified.
7. Contradictions: list each in 9. Open Questions as "CONFLICT: <side A> vs <side B> - needs stakeholder resolution (<stakeholders>)" without choosing a side. Also list decisions_pending and missing_information there.
8. 8. Assumptions: only assumptions stated in the source. If you had to interpret something, list it prefixed with "[PRD Genie interpretation - confirm]". If none: "None stated in source."
9. 7. Dependencies table: from the extraction; unknown status/ETA -> Status "Unknown" and Risk "High - ETA unknown" (or the stated risk).
10. 10. Timeline: fill only dates or periods stated in the source; all others "TBD".
11. 1. Product Overview: Product Name from the extraction (or "TBD"), Document Version "0.1 (AI draft)", Status "Draft", Date = TODAY, Author = "PRD Genie (AI draft) - Owner: <PM name if stated, else TBD>".
12. Success Metrics: only measurable targets stated in the source; otherwise "TBD - needs stakeholder input". Persona "Current Workaround": only if stated, else "Not stated".
13. 6. Out of Scope: only items the source explicitly excludes or defers; otherwise "Not specified in source".

Return ONLY one JSON object:
{
  "prd_markdown": "the full PRD in markdown, starting with '# Product Requirements Document (PRD)'",
  "features": [{"feature_id": "F-01", "name": "string", "requirement_ids": ["REQ-001"], "fr_ids": ["FR-001"], "nfr_ids": ["NFR-001"]}],
  "sections_without_source_content": ["section names"]
}`;

const USER = `TODAY: ${new Date().toISOString().slice(0, 10)}
${$json.human_reviewed ? 'NOTE: The EXTRACTION below was reviewed and approved by the PM (human-in-the-loop). Treat it as the source of truth.\n' : ''}
TEMPLATE:
<<<TEMPLATE
${$json.prd_template}
TEMPLATE>>>

EXTRACTION:
<<<EXTRACTION
${JSON.stringify($json.extraction, null, 2)}
EXTRACTION>>>

SOURCE:
<<<SOURCE
${$json.input_text || '(not provided - use the PM-reviewed extraction only)'}
SOURCE>>>`;

function buildRequest(system, user) {
  const c = $json.config;
  const req = {
    model: c.model,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  };
  if (c.temperature !== null && c.temperature !== undefined) req.temperature = c.temperature;
  return { json: { ...$json, _stage_start: new Date().toISOString(), llm_request: req } };
}

return buildRequest(SYSTEM, USER);

function parseLLM(resp) {
  const raw = resp?.choices?.[0]?.message?.content ?? '';
  try { return JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) {} }
    return { _parse_error: true, _raw: raw };
  }
}
function traceEntry(stage, prev, resp, parsed) {
  return {
    stage,
    model: resp.model || prev.config.model,
    start_time: prev._stage_start,
    end_time: new Date().toISOString(),
    input: prev.llm_request.messages,
    output: parsed,
    usage: { input: resp.usage?.prompt_tokens || 0, output: resp.usage?.completion_tokens || 0 },
  };
}
function nextCtx(prevNodeName, stage) {
  const prev = $(prevNodeName).item.json;
  const parsed = parseLLM($json);
  const ctx = { ...prev };
  delete ctx.llm_request;
  delete ctx._stage_start;
  return { ctx, parsed, entry: traceEntry(stage, prev, $json, parsed) };
}

const { ctx, parsed, entry } = nextCtx('Prepare PRD Prompt', 'prd_generator');
ctx.trace = [...ctx.trace, entry];
if (parsed._parse_error || !parsed.prd_markdown) ctx.error = 'PRD Generator returned invalid JSON.';
ctx.prd = parsed;
return { json: ctx };

// Agent 3 — Story Breakdown: PRD features -> Epics -> Features -> User Stories with priority.
const SYSTEM = `You are the STORY BREAKDOWN agent of "PRD Genie". Convert the PRD into Epics -> Features -> User Stories.

RULES
1. Use only features and requirements present in the PRD and EXTRACTION. Add no new functionality.
2. Every story uses the format: "As a <persona>, I want <capability>, so that <benefit>."
   - Use the specific persona named in the source (e.g. Admin, End User, Auditor, Finance team). When several personas are named, create SEPARATE stories per persona - never merge them into a generic "user". Use "user" only when the source names no persona.
   - If the benefit is not stated in the source write "so that <benefit to be confirmed by PM>".
3. Acceptance criteria per story: copy the verbatim acceptance criteria from the EXTRACTION/PRD ("derived": false). Only when a requirement has none, add criteria restating what the requirement itself makes testable ("derived": true). Do NOT add criteria the source does not support (no extra error handling, accessibility, edge cases, etc.).
4. Priority per story: "Must Have" | "Should Have" | "Nice to Have", with a one-line rationale grounded in the source (e.g. "stated as a hard requirement by Sarah"). With no explicit signal, suggest one and say "suggested - no explicit priority in source".
5. Non-functional requirements become acceptance criteria on the relevant stories, or an "enabler" story when they apply across stories. Keep numbers verbatim.
6. Traceability: each story lists source_requirement_ids (REQ ids).
7. Stories that depend on an unresolved conflict or ambiguity get "status": "blocked - needs clarification"; do not silently resolve the conflict.

Return ONLY one JSON object:
{"epics": [{"epic_id": "EP-01", "title": "string", "description": "string", "features": [{"feature_id": "F-01", "title": "string", "stories": [{"story_id": "US-001", "persona": "string", "story": "As a ..., I want ..., so that ...", "type": "user_story | enabler", "priority": "Must Have | Should Have | Nice to Have", "priority_rationale": "string", "acceptance_criteria": [{"text": "string", "derived": false}], "source_requirement_ids": ["REQ-001"], "status": "ready | blocked - needs clarification"}]}]}]}`;

const USER = `PRD:
<<<PRD
${$json.prd?.prd_markdown || ''}
PRD>>>

PRD FEATURE MAP:
${JSON.stringify($json.prd?.features || [], null, 2)}

EXTRACTION (requirements, personas, contradictions, dependencies):
${JSON.stringify({
  personas: $json.extraction?.personas || [],
  requirements: $json.extraction?.requirements || [],
  contradictions: $json.extraction?.contradictions || [],
  dependencies: $json.extraction?.dependencies || [],
}, null, 2)}`;

function buildRequest(system, user) {
  const c = $json.config;
  const req = {
    model: c.model,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  };
  if (c.temperature !== null && c.temperature !== undefined) req.temperature = c.temperature;
  return { json: { ...$json, _stage_start: new Date().toISOString(), llm_request: req } };
}

return buildRequest(SYSTEM, USER);

