}
function nextCtx(prevNodeName, stage) {
  const prev = $(prevNodeName).item.json;
  const parsed = parseLLM($json);
  const ctx = { ...prev };
  delete ctx.llm_request;
  delete ctx._stage_start;
  return { ctx, parsed, entry: traceEntry(stage, prev, $json, parsed) };
}

const { ctx, parsed, entry } = nextCtx('Prepare Story Prompt', 'story_breakdown');
ctx.trace = [...ctx.trace, entry];
if (parsed._parse_error) ctx.error = 'Story Breakdown returned invalid JSON.';
ctx.stories = parsed;
return { json: ctx };

// Agent 4 (extended) — Gap Analyzer: missing / ambiguous / conflicting info -> clarification questions.
const SYSTEM = `You are the GAP ANALYZER agent of "PRD Genie". Identify missing, ambiguous or conflicting information that would stop engineering from estimating or building, and write clarification questions for stakeholders.

RULES
- Use only the EXTRACTION, PRD and STORIES given. Do not answer the questions yourself and do not propose solutions as facts.
- Every contradiction in the extraction must appear in conflicts_to_resolve, with each position quoted neutrally.
- Unknown ETAs / owners on dependencies are risks.
- Ask each question to the stakeholder named in the source who can answer it; use "PM" if nobody is named.

Return ONLY one JSON object:
{"readiness": "ready | needs_clarification | blocked", "readiness_reason": "string",
 "gaps": [{"gap_id": "GAP-01", "category": "Scope | Users/Personas | Metrics | NFR | Data | Dependency | Timeline | Ownership | Conflict | Budget | Other", "description": "string", "severity": "blocker | high | medium | low", "related_ids": ["REQ-001", "US-001"], "clarification_question": "string", "ask_whom": "string"}],
 "conflicts_to_resolve": [{"topic": "string", "positions": ["string"], "decision_owner": "string"}],
 "risks": [{"risk": "string", "likelihood": "high | medium | low", "impact": "high | medium | low", "mitigation_question": "string"}]}`;

const USER = `EXTRACTION:
${JSON.stringify($json.extraction, null, 2)}

PRD:
<<<PRD
${$json.prd?.prd_markdown || ''}
PRD>>>

STORIES:
${JSON.stringify($json.stories, null, 2)}`;

function buildRequest(system, user) {
  const c = $json.config;
  const req = {
    model: c.model,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  };
  if (c.temperature !== null && c.temperature !== undefined) req.temperature = c.temperature;
  return { json: { ...$json, _stage_start: new Date().toISOString(), llm_request: req } };
}

return buildRequest(SYSTEM, USER);

