const { ctx, parsed, entry } = nextCtx('Prepare Gap Prompt', 'gap_analyzer');
ctx.trace_gap = [entry];
ctx.gap_analysis = parsed;
return { json: ctx };

// Agent 5 (extended) — Scope Estimator: T-shirt size per story, flags underspecified stories.
const SYSTEM = `You are the SCOPE ESTIMATOR agent of "PRD Genie". Assign a T-shirt size (S / M / L / XL) to every story using only complexity signals visible in the STORIES and CONTEXT. Do NOT invent hours, dates or team sizes.

SIZING GUIDE
- S: single well-defined change, at most 2 acceptance criteria, no integration.
- M: several acceptance criteria, or one integration, or UI + API work.
- L: multiple components, strict NFR threshold (latency, concurrency), new data pipeline or export engine.
- XL: cross-team dependency, new service, unresolved architecture decision or conflict - recommend splitting.
Flag a story as underspecified when its persona, benefit, acceptance criteria or target values are missing/ambiguous, or it is blocked.

Return ONLY one JSON object:
{"estimates": [{"story_id": "US-001", "size": "S | M | L | XL", "complexity_signals": ["string"], "underspecified": false, "underspecified_reason": "string", "confidence": "high | medium | low", "split_recommendation": "string or null"}],
 "summary": {"S": 0, "M": 0, "L": 0, "XL": 0, "underspecified_count": 0}}`;

const USER = `STORIES:
${JSON.stringify($json.stories, null, 2)}

CONTEXT (NFRs, dependencies, conflicts from the extraction):
${JSON.stringify({
  non_functional: ($json.extraction?.requirements || []).filter(r => r.type !== 'functional'),
  dependencies: $json.extraction?.dependencies || [],
  contradictions: $json.extraction?.contradictions || [],
}, null, 2)}`;

function buildRequest(system, user) {
  const c = $json.config;
  const req = {
    model: c.model,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  };
  if (c.temperature !== null && c.temperature !== undefined) req.temperature = c.temperature;
  return { json: { ...$json, _stage_start: new Date().toISOString(), llm_request: req } };
}

return buildRequest(SYSTEM, USER);

