}

const { ctx, parsed, entry } = nextCtx('Prepare Scope Prompt', 'scope_estimator');
ctx.trace_scope = [entry];
ctx.scope_estimates = parsed;
return { json: ctx };

// Builds the final PRD package (markdown) for every outcome: PRD generated / awaiting PM review / insufficient input / error.
const j = { ...$json };
const ex = j.extraction || {};
j.trace = [...(j.trace || []), ...(j.trace_gap || []), ...(j.trace_scope || [])];
delete j.trace_gap; delete j.trace_scope; delete j.llm_request; delete j._stage_start;

const cell = s => String(s ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const li = (arr, f) => (arr && arr.length) ? arr.map(x => '- ' + f(x)).join('\n') : '- _None_';

let status;
if (j.error) status = 'error';
else if (j.prd?.prd_markdown) status = 'prd_generated';
else if (j.mode === 'extract_only' && ex.input_assessment?.sufficiency !== 'insufficient') status = 'awaiting_pm_review';
else status = 'insufficient_input';
j.status = status;

function extractionSection() {
  const reqs = ex.requirements || [];
  const rows = reqs.map(r => `| ${cell(r.id)} | ${cell(r.statement)} | ${cell(r.type)}${r.nfr_category ? ' / ' + cell(r.nfr_category) : ''} | ${cell(r.certainty)} | ${cell(r.priority_signal)} | "${cell(r.source_quote)}" |`).join('\n');
  return [
    `**Input assessment:** ${cell(ex.input_assessment?.sufficiency || 'n/a')} - ${ex.input_assessment?.sufficiency_reason || ''}`,
    ex.input_assessment?.summary ? `\n**Summary:** ${ex.input_assessment.summary}` : '',
    '\n### Requirements',
    reqs.length ? '| ID | Requirement | Type | Certainty | Priority signal | Source quote |\n|----|----|----|----|----|----|\n' + rows : '_No requirements could be extracted._',
    '\n### Stakeholders',
    li(ex.stakeholders, s => `**${s.name}**${s.role ? ' (' + s.role + ')' : ''}: ${(s.viewpoints || []).join('; ')}`),
    '\n### Personas',
    li(ex.personas, p => `**${p.name}**: ${(p.needs || []).join('; ')}`),
    '\n### Deadlines',
    li(ex.deadlines, d => `${d.description}: ${d.date_or_period}`),
    '\n### Dependencies',
    li(ex.dependencies, d => `${d.description} - owner: ${d.owner || 'unknown'}, status: ${d.status || 'unknown'}, ETA: ${d.eta || 'unknown'}${d.risk ? ' - RISK: ' + d.risk : ''}`),
    '\n### Contradictions (need stakeholder resolution)',
    li(ex.contradictions, c => `**${c.topic}**: "${c.source_a}" vs "${c.source_b}" (${(c.stakeholders_involved || []).join(', ')})`),
    '\n### Ambiguities',
    li(ex.ambiguities, a => `${a.item} - ${a.why_ambiguous} ("${a.source_quote}")`),
    '\n### Missing information / clarification questions',
    li(ex.missing_information, m => `**${m.area}:** ${m.question}`),
  ].join('\n');
}

function storiesSection() {
  const sizes = {};
  (j.scope_estimates?.estimates || []).forEach(e => { sizes[e.story_id] = e; });
  const rows = [];
  for (const ep of (j.stories?.epics || [])) {
    for (const f of (ep.features || [])) {
      for (const s of (f.stories || [])) {
        const est = sizes[s.story_id] || {};
        const ac = (s.acceptance_criteria || []).map(a => (a.derived ? '(derived) ' : '') + a.text).join('<br>');
        rows.push(`| ${cell(ep.epic_id + ' ' + ep.title)} | ${cell(f.feature_id + ' ' + f.title)} | ${cell(s.story_id)} | ${cell(s.story)} | ${cell(s.priority)} | ${cell(est.size || '-')}${est.underspecified ? ' ⚠' : ''} | ${cell(ac)} | ${cell(s.status || 'ready')} |`);
      }
    }
  }
  if (!rows.length) return '_No stories generated._';
  return '| Epic | Feature | ID | User Story | Priority | Size | Acceptance Criteria | Status |\n|----|----|----|----|----|----|----|----|\n' + rows.join('\n');
}

function scopeSection() {
  const est = j.scope_estimates?.estimates || [];
  if (!est.length) return '_No estimates._';
  const sum = j.scope_estimates?.summary || {};
  return `**Summary:** S=${sum.S ?? 0}, M=${sum.M ?? 0}, L=${sum.L ?? 0}, XL=${sum.XL ?? 0}, underspecified=${sum.underspecified_count ?? 0}\n\n` +
    '| Story | Size | Confidence | Complexity signals | Underspecified |\n|----|----|----|----|----|\n' +
    est.map(e => `| ${cell(e.story_id)} | ${cell(e.size)} | ${cell(e.confidence)} | ${cell((e.complexity_signals || []).join('; '))} | ${e.underspecified ? 'Yes - ' + cell(e.underspecified_reason) : 'No'} |`).join('\n');
}

function gapSection() {
  const g = j.gap_analysis || {};
  return [
    `**Readiness:** ${g.readiness || 'n/a'} - ${g.readiness_reason || ''}`,
    '\n| Gap | Category | Severity | Clarification question | Ask |\n|----|----|----|----|----|',
    ...(g.gaps || []).map(x => `| ${cell(x.gap_id)} | ${cell(x.category)} | ${cell(x.severity)} | ${cell(x.clarification_question)} | ${cell(x.ask_whom)} |`),
    '\n**Conflicts to resolve**',
    li(g.conflicts_to_resolve, c => `**${c.topic}** - positions: ${(c.positions || []).join(' / ')} - decision owner: ${c.decision_owner || 'TBD'}`),
    '\n**Risks**',
    li(g.risks, r => `${r.risk} (likelihood ${r.likelihood}, impact ${r.impact}) - ${r.mitigation_question}`),
  ].join('\n');
}

const header = `<!-- PRD Genie run ${j.run_id} | status: ${status} | test: ${j.test_id || '-'} -->\n`;
let md;
if (status === 'prd_generated') {
  md = header + j.prd.prd_markdown +
    '\n\n---\n## 11. Epics & User Stories\n' + storiesSection() +
    '\n\n## 12. Scope Estimates (T-shirt sizes)\n' + scopeSection() +
    '\n\n## 13. Gap Analysis & Clarification Questions\n' + gapSection() +
    '\n\n---\n## Appendix A - Requirement Extraction (traceability)\n' + extractionSection();
} else if (status === 'awaiting_pm_review') {
  md = header + '# Requirement Extraction - awaiting PM review\n\n' +
    '> Human-in-the-loop: review / edit the `extraction` JSON, then POST it back with `"mode": "from_extraction"` to generate the PRD and stories.\n\n' +
    extractionSection();
} else if (status === 'insufficient_input') {
  md = header + '# ⚠ Insufficient input - no PRD generated\n\n' +
    `PRD Genie did not generate a PRD because ${j.stop_reason || ex.input_assessment?.sufficiency_reason || 'the input contains no concrete requirements'}. ` +
    'Nothing has been filled in with assumptions. Please answer the questions below and re-run.\n\n' + extractionSection();
} else {
  md = header + `# PRD Genie error\n\n${j.error}\n\n` + extractionSection();
}
j.document_markdown = md;

// Cost & latency accounting (for the cost analysis / observability write-up)
const c = j.config || {};
const tokIn = j.trace.reduce((a, t) => a + (t.usage?.input || 0), 0);
const tokOut = j.trace.reduce((a, t) => a + (t.usage?.output || 0), 0);
j.usage_summary = {
  llm_calls: j.trace.length,
  input_tokens: tokIn,
  output_tokens: tokOut,
  est_cost_usd: +((tokIn * (c.price_per_1m_input_usd || 0) + tokOut * (c.price_per_1m_output_usd || 0)) / 1e6).toFixed(6),
  latency_ms: Date.now() - new Date(j.started_at).getTime(),
  per_stage: j.trace.map(t => ({ stage: t.stage, input_tokens: t.usage?.input || 0, output_tokens: t.usage?.output || 0,
    latency_ms: new Date(t.end_time) - new Date(t.start_time) })),
};
return { json: j };

// Deterministic quality checks (grounding / hallucination) + baseline expectations for T1-T12.
const j = { ...$json };
const ex = j.extraction || {};
const norm = s => String(s ?? '').toLowerCase().replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/\s+/g, ' ').trim();
const vals = o => o == null ? [] : typeof o === 'object' ? Object.values(o).flatMap(vals) : [String(o)];
const src = norm(j.input_text);

// --- 1. Grounding: every source_quote must exist verbatim in the input -------------------------
const quotes = [];
const add = (kind, id, q) => { if (q) quotes.push({ kind, id, quote: q }); };
(ex.requirements || []).forEach(r => add('requirement', r.id, r.source_quote));
(ex.personas || []).forEach(p => add('persona', p.name, p.source_quote));
(ex.stakeholders || []).forEach(s => add('stakeholder', s.name, s.source_quote));
(ex.deadlines || []).forEach(d => add('deadline', d.description, d.source_quote));
(ex.dependencies || []).forEach(d => add('dependency', d.description, d.source_quote));
(ex.contradictions || []).forEach(c => { add('contradiction', c.topic, c.source_a); add('contradiction', c.topic, c.source_b); });
(ex.ambiguities || []).forEach(a => add('ambiguity', a.item, a.source_quote));
const isGrounded = q => norm(q).replace(/^["']|["']$/g, '').split(/\.\.\.|…/).map(s => s.trim()).filter(Boolean).every(p => src.includes(p));
const ungrounded = src ? quotes.filter(q => !isGrounded(q.quote)) : [];

// --- 2. Numbers in extracted requirements must appear in the source (no rounding / invention) ---
const numText = (ex.requirements || []).map(r => [r.statement, ...(r.metrics || []).map(m => m.value)].join(' ')).join(' ');
const nums = [...new Set((numText.match(/\d[\d,.]*\d|\d/g) || []).map(n => n.replace(/[.,]+$/, '')))];
const ungroundedNumbers = src ? nums.filter(n => !src.includes(n.toLowerCase())) : [];

j.quality = {
  grounding_checked: !!src,
  quotes_total: quotes.length,
  quotes_grounded: quotes.length - ungrounded.length,
  grounding_ratio: src ? (quotes.length ? +((quotes.length - ungrounded.length) / quotes.length).toFixed(3) : 1) : null,
  ungrounded_items: ungrounded,
  ungrounded_numbers: ungroundedNumbers,
  hallucination_risk: (ungrounded.length || ungroundedNumbers.length) ? 'review' : 'low',
};

// --- 3. Baseline dataset expectations (Problem Statement table T1-T12) --------------------------
const reqs = ex.requirements || [];
const blob = norm(vals(ex).join(' '));
const reqBlob = norm(vals(reqs).join(' '));
const missBlob = norm(vals(ex.missing_information).join(' '));
const prdRaw = j.prd?.prd_markdown || '';
const prdMd = norm(prdRaw);
const stories = (j.stories?.epics || []).flatMap(e => (e.features || []).flatMap(f => f.stories || []));
const storyAC = stories.flatMap(s => s.acceptance_criteria || []);
const has = (s, ...keys) => keys.some(k => s.includes(k));
const C = (name, pass, detail = '') => ({ name, pass: !!pass, detail: String(detail) });
const suff = ex.input_assessment?.sufficiency;
const noPrd = !prdRaw;
const stated = reqs.filter(r => r.certainty === 'stated');
const contradictions = ex.contradictions || [];

const EXPECT = {
  T1: () => [
    C('Not flagged insufficient', suff !== 'insufficient', suff),
    C('Filter by date range extracted', has(reqBlob, 'date')),
    C('Filter by category extracted', has(reqBlob, 'category')),
    C('Filter by status extracted', has(reqBlob, 'status')),
    C('2-second load time extracted', /\b2[\s-]*(seconds?|secs?|s)\b/.test(reqBlob)),
    C('PM Sarah extracted', has(blob, 'sarah')),
    C('Q3 deadline extracted', has(blob, 'q3')),
    C('No requirements outside the transcript (all quotes grounded)', reqs.length > 0 && ungrounded.length === 0 && ungroundedNumbers.length === 0,
      ungrounded.map(u => u.quote).concat(ungroundedNumbers).join(' | ')),
  ],
  T2: () => [
    C('Flagged as ambiguous / insufficient', ['insufficient', 'partial'].includes(suff), suff),
    C('Ambiguities listed', (ex.ambiguities || []).length >= 1),
    C('Missing info listed (>=2)', (ex.missing_information || []).length >= 2),
    C('Missing info covers metrics / format / users (>=2 of 3)', [has(missBlob, 'metric', 'kpi', 'measure'), has(missBlob, 'format', 'visual', 'chart', 'output'), has(missBlob, 'user', 'persona', 'audience', 'who')].filter(Boolean).length >= 2),
    C('No specific requirements invented', stated.length === 0, `${stated.length} stated`),
    C('No PRD generated from vague input', noPrd),
  ],
  T3: () => [
    C('Contradiction identified', contradictions.length >= 1),
    C('Flagged for stakeholder resolution', contradictions.some(c => c.needs_stakeholder_resolution)),
    C('Contradiction covers refresh vs API calls', has(norm(vals(contradictions).join(' ')), '5 second', '5-second', '5s') && has(norm(vals(contradictions).join(' ')), 'api')),
  ],
  T4: () => {
    const acSrc = norm(reqs.flatMap(r => r.acceptance_criteria_verbatim || []).join(' '));
    const acStory = norm(storyAC.map(a => a.text).join(' '));
    return [
      C('AC "PDF must include company logo" extracted verbatim', has(acSrc, 'pdf must include company logo', 'company logo')),
      C('AC "CSV must preserve formulas" extracted verbatim', has(acSrc, 'csv must preserve formulas', 'preserve formulas')),
      C('User stories generated', stories.length >= 1, stories.length),
      C('Stories use the logo criterion', has(acStory, 'logo')),
      C('Stories use the formulas criterion', has(acStory, 'formula')),
      C('No extra (derived) acceptance criteria added', storyAC.filter(a => a.derived).length === 0, storyAC.filter(a => a.derived).map(a => a.text).join(' | ')),
    ];
  },
  T5: () => [
    C('Flagged as insufficient', suff === 'insufficient', suff),
    C('Missing info listed (>=3)', (ex.missing_information || []).length >= 3, (ex.missing_information || []).length),
    C('Covers dashboard / real-time / budget', has(missBlob, 'dashboard') && has(missBlob, 'real-time', 'real time', 'realtime') && has(missBlob, 'budget')),
    C('No gaps filled (no PRD generated)', noPrd),
  ],
  T6: () => [
    C('Engineering viewpoint (microservices) captured', has(blob, 'microservice')),
    C('Design viewpoint (single-page app) captured', has(blob, 'single-page', 'single page', 'spa')),
    C('PM viewpoint (ship by March) captured', has(blob, 'march')),
    C('Three stakeholders captured', (ex.stakeholders || []).length >= 3, (ex.stakeholders || []).length),
    C('Tensions identified', contradictions.length >= 1, contradictions.length),
  ],
  T7: () => [
    C('10,000 concurrent users (exact)', has(reqBlob, '10,000')),
    C('200ms at p95 (exact)', has(reqBlob, '200ms', '200 ms') && has(reqBlob, 'p95')),
    C('Salesforce REST API v52 (exact)', has(reqBlob, 'v52') && has(reqBlob, 'salesforce')),
    C('Classified as NFRs (>=2)', reqs.filter(r => r.type === 'non_functional').length >= 2),
    C('Numbers not rounded or modified', !has(reqBlob, '10k', '10 000', '0.2s', '0.2 s') && ungroundedNumbers.length === 0, ungroundedNumbers.join(', ')),
  ],
  T8: () => {
    const pBlob = norm((ex.personas || []).map(p => p.name).join(' | '));
    const sp = norm(stories.map(s => s.persona + ' ' + s.story).join(' | '));
    return [
      C('3 personas identified', (ex.personas || []).length >= 3, pBlob),
      C('Admin persona', has(pBlob, 'admin')),
      C('End User persona', has(pBlob, 'end user', 'end-user')),
      C('Auditor persona', has(pBlob, 'auditor')),
      C('Separate stories per persona', has(sp, 'admin') && has(sp, 'end user', 'end-user') && has(sp, 'auditor')),
      C('No generic merged "user" stories', !stories.some(s => norm(s.persona) === 'user')),
    ];
  },
  T9: () => [
    C('Flagged as no requirements extractable', suff === 'insufficient', suff),
    C('No requirements extracted', stated.length === 0),
    C('No PRD generated', noPrd),
  ],
  T10: () => {
    const dBlob = norm(vals(ex.dependencies).join(' '));
    return [
      C('SSO feature extracted', has(reqBlob, 'sso')),
      C('Dependency on auth service / Team Alpha', has(dBlob, 'alpha') && has(dBlob, 'auth')),
      C('Unknown ETA flagged as risk', (ex.dependencies || []).some(d => d.risk && has(norm(vals(d).join(' ')), 'unknown', 'eta'))),
    ];
  },
  // T11 / T12 are evaluated on the T1 run (PRD from T1 extraction, stories from that PRD)
  T11: () => {
    const sections = ['product overview', 'goals and objectives', 'user personas', 'feature requirements', 'functional requirements',
      'non-functional requirements', 'acceptance criteria', 'out of scope', 'dependencies', 'assumptions', 'open questions', 'timeline'];
    const missing = sections.filter(s => !prdMd.includes(s));
    const frIds = new Set(prdRaw.match(/FR-\d{3}/g) || []);
    return [
      C('PRD generated', !noPrd),
      C('All template sections present', missing.length === 0, missing.join(', ')),
      C('FR count within extracted requirements', frIds.size > 0 && frIds.size <= reqs.length, `${frIds.size} FR vs ${reqs.length} REQ`),
      C('No out-of-source features in PRD', !has(prdMd, 'export', 'competitor', 'sso', 'dark mode', 'salesforce')),
    ];
  },
  T12: () => [
    C('Epics produced', (j.stories?.epics || []).length >= 1),
    C('User stories produced', stories.length >= 1, stories.length),
    C('All stories in "As a [user]" format', stories.length > 0 && stories.every(s => /^as an? /i.test((s.story || '').trim()))),
    C('Priority suggestions on all stories', stories.length > 0 && stories.every(s => ['must have', 'should have', 'nice to have'].includes(norm(s.priority)))),
  ],
};

const ids = j.test_id === 'T1' ? ['T1', 'T11', 'T12'] : (EXPECT[j.test_id] ? [j.test_id] : []);
j.eval = ids.length ? {
  results: ids.map(id => {
    const checks = EXPECT[id]();
    return { test_id: id, passed: checks.filter(c => c.pass).length, total: checks.length, pass: checks.every(c => c.pass), checks };
  }),
} : null;
return { json: j };

// Builds a Langfuse ingestion batch: 1 trace, 1 generation per agent call, scores for grounding & eval.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.config?.langfuse_enabled) continue;
  const rid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
  const now = new Date().toISOString();
  const traceId = j.run_id;
  const batch = [{
    id: rid(), timestamp: now, type: 'trace-create',
    body: {
      id: traceId, name: 'prd-genie', timestamp: j.started_at,
      input: { input_text: j.input_text, mode: j.mode, input_type: j.input_type },
      output: { status: j.status, document_markdown: j.document_markdown },
      tags: ['prd-genie', j.source, j.status, ...(j.test_id ? ['baseline-eval', j.test_id] : [])],
      metadata: { test_id: j.test_id, usage_summary: j.usage_summary, quality: j.quality, human_reviewed: j.human_reviewed },
    },
  }];
  for (const t of (j.trace || [])) {
    batch.push({
      id: rid(), timestamp: now, type: 'generation-create',
      body: {
        id: rid(), traceId, name: t.stage, startTime: t.start_time, endTime: t.end_time, model: t.model,
        input: t.input, output: t.output,
        usage: { input: t.usage?.input || 0, output: t.usage?.output || 0, unit: 'TOKENS' },
      },
    });
  }
  const score = (name, value, comment) => batch.push({ id: rid(), timestamp: now, type: 'score-create', body: { id: rid(), traceId, name, value, comment } });
  if (j.quality?.grounding_ratio !== null && j.quality?.grounding_ratio !== undefined) {
    score('grounding_ratio', j.quality.grounding_ratio, `${j.quality.quotes_grounded}/${j.quality.quotes_total} source quotes found verbatim`);
    score('ungrounded_numbers', j.quality.ungrounded_numbers.length, j.quality.ungrounded_numbers.join(', '));
  }
  for (const r of (j.eval?.results || [])) {
    score(`eval_${r.test_id}`, +(r.passed / r.total).toFixed(3), r.checks.filter(c => !c.pass).map(c => 'FAIL: ' + c.name).join('; ') || 'all checks passed');
  }
  out.push({ json: { langfuse_host: j.config.langfuse_host, payload: { batch } } });
}
return out;

// API response (webhook) / sub-workflow result (eval harness).
const j = $json;
return {
  json: {
    run_id: j.run_id,
    status: j.status,                       // prd_generated | awaiting_pm_review | insufficient_input | error
    test_id: j.test_id,
    mode: j.mode,
    human_reviewed: j.human_reviewed,
    error: j.error || null,
    document_markdown: j.document_markdown, // full PRD package / extraction report
    extraction: j.extraction || null,       // edit this and POST back with mode=from_extraction (human-in-the-loop)
    prd_markdown: j.prd?.prd_markdown || null,
    epics: j.stories?.epics || [],
    scope_estimates: j.scope_estimates || null,
    gap_analysis: j.gap_analysis || null,
    quality: j.quality,
    eval: j.eval,
    usage: j.usage_summary,
  },
};

// Aggregates the baseline run into a single report (copy report_markdown into your submission).
const rows = [];
let checksPassed = 0, checksTotal = 0, testsPassed = 0, testsTotal = 0, tokIn = 0, tokOut = 0, cost = 0;
const details = [];
for (const it of $input.all()) {
  const r = it.json;
  tokIn += r.usage?.input_tokens || 0; tokOut += r.usage?.output_tokens || 0; cost += r.usage?.est_cost_usd || 0;
  const results = r.eval?.results || [{ test_id: r.test_id || r.run_id, passed: 0, total: 0, pass: null, checks: [] }];
  for (const e of results) {
    checksPassed += e.passed; checksTotal += e.total;
    if (e.pass !== null) { testsTotal++; if (e.pass) testsPassed++; }
    const failed = e.checks.filter(c => !c.pass).map(c => c.name + (c.detail ? ` (${c.detail})` : ''));
    rows.push(`| ${e.test_id} | ${r.status} | ${e.pass === null ? 'n/a' : e.pass ? 'PASS' : 'FAIL'} | ${e.passed}/${e.total} | ${r.quality?.grounding_ratio ?? 'n/a'} | ${(r.usage?.input_tokens || 0) + (r.usage?.output_tokens || 0)} | ${(r.usage?.est_cost_usd || 0).toFixed(5)} | ${failed.join('; ').replace(/\|/g, '/') || '-'} |`);
    details.push({ test_id: e.test_id, status: r.status, pass: e.pass, checks: e.checks, run_id: r.run_id });
  }
}
const report = [
  '# PRD Genie - Baseline Evaluation Report',
  `Run at ${new Date().toISOString()}`,
  '',
  `**Tests passed:** ${testsPassed}/${testsTotal}  |  **Checks passed:** ${checksPassed}/${checksTotal} (${checksTotal ? (100 * checksPassed / checksTotal).toFixed(1) : 0}%)`,
  `**Tokens:** ${tokIn} in / ${tokOut} out  |  **Estimated cost:** $${cost.toFixed(4)}  (avg $${(cost / Math.max(1, $input.all().length)).toFixed(4)} per input)`,
  '',
  '| Test | Pipeline status | Result | Checks | Grounding ratio | Tokens | Cost (USD) | Failed checks |',
  '|----|----|----|----|----|----|----|----|',
  ...rows,
].join('\n');
return [{ json: { report_markdown: report, tests_passed: testsPassed, tests_total: testsTotal, checks_passed: checksPassed, checks_total: checksTotal, est_cost_usd: +cost.toFixed(6), details } }];
